  'error_null', '20',
  'regex_rules_json', wwv_flow_string.join(wwv_flow_t_varchar2(
    '{',
    '  "EMAIL": "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$",',
    '  "PHONE": "^[0-9+ -]{7,20}$",',
