    '  /*case when level = 3 then ''ABC'' else */''0300-123456''||level as phone,',
    '  /*case when level in (4,6) then 100 else*/ level as order_id,',
    '  case when level in (4,6) then null else ''A-''||level end as Test_Column',
    'from dual',
    'connect by level <= 10')),
  'warn_duplicate', '1',
